<?php
/** Slice 3 — receipts, catch weight and the temperature check, a receipt against a PO (ledger.md "Proof": Receipts, Receipt against a PO). */
require __DIR__ . '/lib.php';
$w = ledger_world();
$bea = person(28); $dana = person(30); $ann = person(29); $marco = person(27);

echo "1. A draft, its header\n";
$r = post($bea, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco'], 'received_on' => date('Y-m-d'), 'delivery_note_ref' => 'DN-1001']);
$g1 = last_id('goods_receipts');
ok($r['code'] === 302 && str_contains($r['location'], '/receipts/' . $g1) && one('SELECT status FROM goods_receipts WHERE id = :g', ['g' => $g1]) === 'draft', 'Bea starts a draft at the Dry store from Sysco; lands on the receiving screen');
ok(preg_match('/^GR-/', (string) one('SELECT number FROM goods_receipts WHERE id = :g', ['g' => $g1])) === 1 && (int) one('SELECT scope_id FROM goods_receipts WHERE id = :g', ['g' => $g1]) === DOWNTOWN, 'numbered GR-… at Downtown');
$ev = q("SELECT * FROM activity_log WHERE action = 'receipt.draft' AND entity_id = :g", ['g' => $g1])[0] ?? null;
ok($ev !== null && (int) $ev['scope_id'] === DOWNTOWN && (int) $ev['actor_member_id'] === 28, 'receipt.draft logged with scope_id and the actor');
$h = page($bea, '/receipts/' . $g1)['body'];
ok(str_contains($h, 'id="receipt-line-form"') && str_contains($h, 'id="receipt-line-form-field-ingredient-open"') && str_contains($h, 'id="receipt-line-form-field-qty"') && str_contains($h, 'id="receipt-line-form-field-unit"'), 'the receiving screen: the line form with the picker, the quantity and the unit side by side');
ok(!str_contains($h, 'id="receipt-line-form-field-unit_cost"'), 'Kitchen sees no cost field (Downtown walls cost from Kitchen)');
ok(str_contains($h, 'data-entity="goods_receipt"') && str_contains($h, 'data-record-id="' . $g1 . '"'), 'the page stamps its entity and record');
ok(str_contains($h, 'id="receipt-line-form-catch-weight"') && str_contains($h, 'id="receipt-line-form-temperature"'), 'with no ingredient chosen the catch-weight and temperature fields are rendered (the form works without JavaScript)');
$r = post($bea, '/receipts/save.php', ['area' => $w['dry'], 'received_on' => date('Y-m-d', strtotime('+2 days'))]);
ok($r['code'] === 422 && has($r, 'not received in the future'), 'a receipt dated in the future: 422 in words');
$r = post($bea, '/receipts/save.php', ['area' => $w['awalkin']]);
ok($r['code'] === 422 && has($r, 'not an active storage area of the site'), 'an area of another site: 422');
$r = post($ann, '/receipts/save.php', ['area' => $w['dry']]);
ok($r['code'] === 403, 'a Viewer cannot start a receipt (403)');

echo "2. Lines: units, catch weight, temperature, cost walls\n";
$r = post($bea, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['flour'], 'qty' => '2', 'unit' => 'bag50', 'unit_cost' => '25']);
ok($r['code'] === 422 && has($r, 'not entered by you'), "Bea sends a cost where Kitchen sees none: 422 in words");
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['flour'], 'qty' => '2', 'unit' => 'bag50', 'unit_cost' => '25']);
$l1 = last_id('goods_receipt_lines');
ok($r['code'] === 302 && str_contains($r['location'], '#receipt-line-row-' . $l1), 'Dana adds 2 bag50 of flour at $25; lands on the line');
ok(near(one('SELECT qty_base FROM goods_receipt_lines WHERE id = :l', ['l' => $l1]), 45359.237, 0.001), 'the base quantity: 45 359.237 g');
ok(near(one('SELECT cost_per_base FROM goods_receipt_lines WHERE id = :l', ['l' => $l1]), 25 / 22679.6185, 0.000001), 'the cost per gram: $0.001102');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['chicken'], 'qty' => '1', 'unit' => 'case', 'weight_qty' => '38.5', 'weight_unit' => 'lb', 'unit_cost' => '3.10']);
$lc = last_id('goods_receipt_lines');
ok($r['code'] === 302, 'Dana adds a case of chicken by its declared weight');
ok(near(one('SELECT qty_base FROM goods_receipt_lines WHERE id = :l', ['l' => $lc]), 17463.31, 0.01), 'catch weight: the declared 38.5 lb lands as 17 463.31 g (the trigger), not the nominal case');
ok(near(one('SELECT cost_per_base FROM goods_receipt_lines WHERE id = :l', ['l' => $lc]), 3.10 / 453.59237, 0.000001), 'catch weight: $3.10 / lb → $0.006834 / g');
ok(one('SELECT weight_unit_code FROM goods_receipt_lines WHERE id = :l', ['l' => $lc]) === 'lb' && near(one('SELECT weight_qty FROM goods_receipt_lines WHERE id = :l', ['l' => $lc]), 38.5), 'the declared weight and its unit kept on the line');
$r = post($bea, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['egg'], 'qty' => '2', 'unit' => 'case', 'temperature_c' => '3.5', 'temperature_ok' => 'yes']);
$le = last_id('goods_receipt_lines');
ok($r['code'] === 302 && near(one('SELECT qty_base FROM goods_receipt_lines WHERE id = :l', ['l' => $le]), 360) && near(one('SELECT temperature_c FROM goods_receipt_lines WHERE id = :l', ['l' => $le]), 3.5) && one('SELECT temperature_ok FROM goods_receipt_lines WHERE id = :l', ['l' => $le]) === true, 'Bea adds 2 cases of eggs (360) at 3.5 °C OK');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['lime'], 'qty' => '2', 'unit' => 'kg']);
ok($r['code'] === 422 && has($r, 'has no each-weight'), 'limes in kg: 422 — "limes have no each-weight" (the schema\'s sentence)');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['flour'], 'qty' => '2', 'unit' => 'l']);
ok($r['code'] === 422 && has($r, 'has no density'), 'flour in litres: 422 — no density, a volume cannot become a weight');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['flour'], 'qty' => '0', 'unit' => 'bag50']);
ok($r['code'] === 422 && has($r, 'more than zero'), 'a zero quantity: 422');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['egg'], 'qty' => '1', 'unit' => 'case', 'discrepancy_kind' => 'stolen']);
ok($r['code'] === 422 && has($r, 'discrepancy is one of'), 'an unknown discrepancy: 422');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['gin'], 'qty' => '2', 'unit' => 'case6', 'unit_cost' => '108', 'putaway_area' => $w['bar']]);
$lg = last_id('goods_receipt_lines');
ok($r['code'] === 302 && (int) one('SELECT putaway_area_id FROM goods_receipt_lines WHERE id = :l', ['l' => $lg]) === $w['bar'] && near(one('SELECT qty_base FROM goods_receipt_lines WHERE id = :l', ['l' => $lg]), 9000), 'gin: 2 case6 (9 000 ml) put away in the Bar');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'supplier_item' => 'SY-EGG15', 'qty' => '1']);
$lsi = last_id('goods_receipt_lines');
ok($r['code'] === 302 && (int) one('SELECT ingredient_id FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]) === $w['egg'] && one('SELECT purchase_unit_code FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]) === 'case' && near(one('SELECT unit_cost FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]), 54), 'a supplier item by SKU fills the ingredient, the purchase unit and the last price ($54)');
$r = post($dana, '/receipts/line.php', ['receipt_line' => $lsi, 'qty' => '1', 'unit' => 'flat', 'discrepancy_kind' => 'short', 'discrepancy_note' => 'one flat only']);
ok($r['code'] === 302 && near(one('SELECT qty_base FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]), 30) && one('SELECT discrepancy_kind FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]) === 'short' && near(one('SELECT unit_cost FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]), 54), 'a short line edited in place: one flat, marked short, the cost kept');
$r = post($dana, '/receipts/line-remove.php', ['receipt_line' => $lsi]);
ok($r['code'] === 302 && (int) one('SELECT count(*) FROM goods_receipt_lines WHERE id = :l', ['l' => $lsi]) === 0, 'a line removed from the draft');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['lime'], 'qty' => '1', 'unit' => 'case', 'unit_cost' => '38', 'temperature_c' => '7', 'temperature_ok' => 'no']);
ok($r['code'] === 302, 'limes: 1 case at $38, a temperature NOT OK');
ok((int) one('SELECT count(*) FROM goods_receipt_lines WHERE goods_receipt_id = :g', ['g' => $g1]) === 5 && (int) one("SELECT count(*) FROM activity_log WHERE action = 'receipt.line_add' AND entity_id = :g AND ingredient_id IS NOT NULL", ['g' => $g1]) >= 6, 'five lines; every receipt.line_add logged with ingredient_id');
$h = page($dana, '/receipts/' . $g1)['body'];
ok(str_contains($h, 'id="receipt-lines-table"') && str_contains($h, 'id="receipt-line-row-' . $l1 . '"') && str_contains($h, 'id="receipt-line-card-' . $l1 . '"'), 'the lines as a table and as cards (the phone)');
ok(str_contains($h, '45,359.237 g') && str_contains($h, '38.5 lb'), 'the line shows its purchase quantity with the base muted, and the declared weight');
ok(str_contains($h, 'id="receipt-lines-total"') && preg_match('/id="receipt-lines-total">\$[0-9,]+\.[0-9]{2}/', $h) === 1, 'Dana sees the amount at cost in the footer');
$hb = page($bea, '/receipts/' . $g1)['body'];
ok(str_contains($hb, 'id="receipt-lines-total"><span class="text-muted" title="cost withheld">'), 'Bea sees the footer amount withheld');
$r = get_json($bea, '/receipts/' . $g1);
ok($r['code'] === 200 && count($r['json']['data']['receipt']['lines'] ?? []) === 5 && !array_key_exists('unit_cost', $r['json']['data']['receipt']['lines'][0]) && ($r['json']['data']['receipt']['lines'][0]['cost_withheld'] ?? false), 'JSON for Bea: five lines, the cost keys absent and cost_withheld');
$r = get_json($dana, '/receipts/' . $g1);
ok(near($r['json']['data']['receipt']['lines'][1]['cost_per_base'] ?? null, 0.006834, 0.000001), 'JSON for Dana: the chicken line\'s cost per gram');

echo "3. Post\n";
$r = post($bea, '/receipts/post.php', ['receipt' => $g1]);
ok($r['code'] === 302 && one('SELECT status FROM goods_receipts WHERE id = :g', ['g' => $g1]) === 'posted', 'Bea posts the receipt');
ok((int) one("SELECT count(*) FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g AND txn_type = 'receipt'", ['g' => $g1]) === 5, 'five receipt transactions');
ok(near(on_hand($w['flour']), 45359.237, 0.001) && near(on_hand($w['flour'], DOWNTOWN, $w['dry']), 45359.237, 0.001), 'flour on hand 45 359.237 g, in the Dry store');
ok(near(avg_cost($w['flour']), 0.001102, 0.000001), "the site's average for flour $0.001102 / g");
ok(near(on_hand($w['gin'], DOWNTOWN, $w['bar']), 9000) && near(on_hand($w['egg'], DOWNTOWN, $w['dry']), 360), 'gin in the Bar (its put-away), eggs in the receipt\'s area');
ok((int) one("SELECT count(*) FROM price_history WHERE reference_kind = 'goods_receipt' AND reference_id = :g AND old_per_base IS NULL", ['g' => $g1]) === 4, 'price history for the four priced lines, old NULL (the first prices)');
ok(one('SELECT temperature_ok FROM goods_receipts WHERE id = :g', ['g' => $g1]) === false, 'the header\'s temperature: the AND of the lines — one NOT OK → not OK');
ok((string) one("SELECT occurred_at::date FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g LIMIT 1", ['g' => $g1]) === (string) one('SELECT received_at::date FROM goods_receipts WHERE id = :g', ['g' => $g1]), 'the movements are dated at the receipt\'s moment');
$ev = q("SELECT after FROM activity_log WHERE action = 'receipt.post' AND entity_id = :g", ['g' => $g1])[0] ?? null;
$after = json_decode((string) ($ev['after'] ?? '{}'), true);
ok($ev !== null && count($after['lines'] ?? []) === 5 && !isset($after['lines'][0]['value']), 'receipt.post logged with the five lines in base with their units, and no value (Bea sees no cost)');
$h = page($dana, '/receipts/' . $g1)['body'];
ok(str_contains($h, 'id="receipt-movements-table"') && str_contains($h, 'id="receipt-prices-table"') && !str_contains($h, 'id="receipt-line-form"'), 'a posted receipt: the movements and the price rows, no line form');
ok(str_contains($h, 'id="receipt-temperature"') && str_contains($h, 'NOT OK'), 'the header says a temperature was NOT OK');
$r = post($dana, '/receipts/line.php', ['receipt' => $g1, 'ingredient' => $w['flour'], 'qty' => '1', 'unit' => 'bag50']);
ok($r['code'] === 422 && has($r, 'only while it is draft'), "a posted receipt's line.php: 422 — only while it is draft (the trigger's sentence)");
$r = post($dana, '/receipts/post.php', ['receipt' => $g1]);
ok($r['code'] === 422 && has($r, 'only a draft posts'), 'posting it again: 422');
$r = post($dana, '/receipts/cancel.php', ['receipt' => $g1]);
ok($r['code'] === 422 && has($r, 'only a draft is cancelled'), 'cancelling a posted receipt: 422');
$h = page($dana, '/receipts/')['body'];
ok(str_contains($h, 'id="receipt-row-' . $g1 . '"') && str_contains($h, 'feather-thermometer text-danger'), 'the list: the receipt with a red thermometer');

echo "4. The average advances; a price alert; the running cost; a free sample\n";
$r = post($dana, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => 'SMOKE Sysco', 'lines' => json_encode([['ingredient' => 'L-FLOUR', 'qty' => 2, 'unit' => 'bag50', 'unit_cost' => 30], ['ingredient' => 'L-LIME', 'qty' => 1, 'unit' => 'case']])]);
$g2 = last_id('goods_receipts');
ok($r['code'] === 302 && (int) one('SELECT count(*) FROM goods_receipt_lines WHERE goods_receipt_id = :g', ['g' => $g2]) === 2, 'a draft with its lines as JSON (the supplier by name, the ingredients by code)');
post($dana, '/receipts/post.php', ['receipt' => $g2]);
ok(near(avg_cost($w['flour']), 110 / 90718.474, 0.000001), 'the moving average: (2 × $25 + 2 × $30) over 4 bags = $0.0012125 / g (the column keeps six decimals)');
ok((int) one('SELECT count(*) FROM price_alerts WHERE ingredient_id = :i AND pct BETWEEN 19.5 AND 20.5', ['i' => $w['flour']]) === 1, 'a price alert at ~20 % (dry goods threshold 10 %)');
ok(near(one("SELECT unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g AND ingredient_id = :i", ['g' => $g2, 'i' => $w['lime']]), 38 / 200, 0.0001), 'a blank cost on limes lands at the running cost ($0.19), never zero');
ok(near(on_hand($w['lime']), 400), '400 limes on hand');
$r = post($dana, '/receipts/save.php', ['area' => $w['walkin'], 'lines' => json_encode([['ingredient' => 'L-LIME', 'qty' => 10, 'unit' => 'each', 'unit_cost' => 0, 'allow_zero_cost' => 'yes']])]);
$g3 = last_id('goods_receipts');
post($dana, '/receipts/post.php', ['receipt' => $g3]);
ok((float) one("SELECT unit_cost_per_base FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g", ['g' => $g3]) === 0.0, 'allow_zero_cost: a free sample lands at zero');
ok(near(avg_cost($w['lime']), 38 / 200, 0.0001), 'and a zero-cost receipt does not pull the average down');

echo "5. Cancel; a cancelled receipt does not post\n";
post($bea, '/receipts/save.php', ['area' => $w['dry']]);
$g4 = last_id('goods_receipts');
$r = post($bea, '/receipts/cancel.php', ['receipt' => $g4]);
ok($r['code'] === 302 && one('SELECT status FROM goods_receipts WHERE id = :g', ['g' => $g4]) === 'cancelled' && (int) one("SELECT count(*) FROM activity_log WHERE action = 'receipt.cancel' AND entity_id = :g", ['g' => $g4]) === 1, 'Bea cancels a draft; logged');
$r = post($bea, '/receipts/post.php', ['receipt' => $g4]);
ok($r['code'] === 422, 'posting a cancelled receipt: 422');
$r = post($bea, '/receipts/save.php', ['receipt' => $g4, 'notes' => 'x']);
ok($r['code'] === 422 && has($r, 'only a draft'), "a cancelled receipt's header does not change");

echo "6. A header changed; a back-dated receipt\n";
post($dana, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco']]);
$g5 = last_id('goods_receipts');
$r = post($dana, '/receipts/save.php', ['receipt' => $g5, 'received_on' => date('Y-m-d', strtotime('-3 days')), 'invoice_ref' => 'INV-77', 'area' => $w['walkin']]);
ok($r['code'] === 302 && one('SELECT received_on FROM goods_receipts WHERE id = :g', ['g' => $g5]) === date('Y-m-d', strtotime('-3 days')) && one('SELECT invoice_ref FROM goods_receipts WHERE id = :g', ['g' => $g5]) === 'INV-77', 'the header changes: back-dated three days, an invoice number, the Walk-in');
ok((string) one("SELECT (received_at = ri_site_moment(101, received_on, false) + interval '1 hour')::text FROM goods_receipts WHERE id = :g", ['g' => $g5]) === 'true', "a back-dated receipt's moment is the day's opening + 1 hour");
$d = json_decode((string) one("SELECT after FROM activity_log WHERE action = 'receipt.update' AND entity_id = :g ORDER BY id DESC LIMIT 1", ['g' => $g5]), true);
ok(isset($d['received_on'], $d['invoice_ref'], $d['storage_area_id']) && !isset($d['notes']), 'receipt.update logs only what changed');
$h = page($dana, '/receipts/' . $g5 . '/edit')['body'];
ok(str_contains($h, 'id="receipt-form"') && str_contains($h, 'value="INV-77"'), 'the header form (receipt-edit) shows the draft');

echo "7. A receipt against a purchase order\n";
as_member(27);
ri_sql('INSERT INTO purchase_orders (scope_id, supplier_id, storage_area_id, created_by) VALUES (101, :s, :a, 27)', ['s' => $w['sysco'], 'a' => $w['dry']]);
$po = last_id('purchase_orders');
ri_sql("INSERT INTO purchase_order_lines (purchase_order_id, line_no, ingredient_id, supplier_item_id, purchase_unit_code, qty_ordered, qty_ordered_base, unit_cost) VALUES (:p, 1, :i, :si, 'bag50', 3, 0, 30)", ['p' => $po, 'i' => $w['flour'], 'si' => $w['si_flour']]);
ri_sql("SELECT ri_po_send(:p, 27, 'email')", ['p' => $po]);
$pol = (int) one('SELECT id FROM purchase_order_lines WHERE purchase_order_id = :p', ['p' => $po]);
ok(near(one('SELECT ri_on_order(:i, 101)', ['i' => $w['flour']]), 3 * 22679.6185, 0.01), 'a sent PO for 3 bags is on order');
$h = page($dana, '/receipts/new?purchase_order=' . $po)['body'];
ok(str_contains($h, 'id="receipt-po-prefill-row-' . $pol . '"') && str_contains($h, 'id="receipt-po-prefill-check-' . $pol . '"') && str_contains($h, 'value="3"'), "receipt-add with the PO prefills its open line: 3 bag50 to come");
ok(preg_match('/<option value="' . $po . '" selected>/', $h) === 1, 'the PO is chosen in the header and its supplier with it');
$r = post($dana, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco'], 'purchase_order' => $po, 'prefill' => [$pol], 'prefill_qty' => [$pol => '2']]);
$g6 = last_id('goods_receipts');
ok($r['code'] === 302 && (int) one('SELECT purchase_order_line_id FROM goods_receipt_lines WHERE goods_receipt_id = :g', ['g' => $g6]) === $pol && near(one('SELECT qty_received FROM goods_receipt_lines WHERE goods_receipt_id = :g', ['g' => $g6]), 2), 'the prefill makes the line: 2 of the 3 bags, the PO line named');
post($dana, '/receipts/post.php', ['receipt' => $g6]);
ok(one('SELECT status FROM purchase_order_lines WHERE id = :l', ['l' => $pol]) === 'partial' && one('SELECT status FROM purchase_orders WHERE id = :p', ['p' => $po]) === 'partial', 'posting marks the PO line and the PO partial (the hook)');
ok(near(one('SELECT ri_on_order(:i, 101)', ['i' => $w['flour']]), 22679.6185, 0.01), 'one bag still on order');
ok((int) one("SELECT count(*) FROM activity_log WHERE action = 'receipt.post' AND entity_id = :g AND purchase_order_id = :p", ['g' => $g6, 'p' => $po]) === 1, 'receipt.post carries purchase_order_id');
$r = post($dana, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['produce'], 'purchase_order' => $po]);
ok($r['code'] === 422 && has($r, 'not this receipt'), "a PO of another supplier: 422 in words");
$h = page($dana, '/receipts/po-options?supplier=' . $w['sysco'], ['headers' => ['HX-Request: true']])['body'];
ok(str_contains($h, '<option value="' . $po . '"'), "the header's PO select re-lists the supplier's open POs (Pattern A)");

echo "8. kitchen_sees_cost\n";
ri_sql('UPDATE site_settings SET kitchen_sees_cost = true WHERE scope_id = 101');
$bea2 = person(28);
post($bea2, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco']]);
$g7 = last_id('goods_receipts');
$h = page($bea2, '/receipts/' . $g7)['body'];
ok(str_contains($h, 'id="receipt-line-form-field-unit_cost"'), 'with kitchen_sees_cost on, Bea sees the cost field');
$r = post($bea2, '/receipts/line.php', ['receipt' => $g7, 'ingredient' => $w['egg'], 'qty' => '1', 'unit' => 'case', 'unit_cost' => '55']);
ok($r['code'] === 302 && near(one('SELECT unit_cost FROM goods_receipt_lines WHERE goods_receipt_id = :g', ['g' => $g7]), 55), 'and may price a line');
ri_sql('UPDATE site_settings SET kitchen_sees_cost = false WHERE scope_id = 101');
post($dana, '/receipts/cancel.php', ['receipt' => $g7]);
post($dana, '/receipts/cancel.php', ['receipt' => $g5]);
echo "9. A receipt dated inside a closed period lands in the next open one, flagged late\n";
ri_sql("INSERT INTO costing_calendars (name, kind, year_start_on, is_default) VALUES ('SMOKE weeks', 'week', date_trunc('year', current_date)::date, false)");
$cal = last_id('costing_calendars');
ri_sql("INSERT INTO periods (scope_id, calendar_id, no, fiscal_year, starts_on, ends_on, status, closed_at, closed_by) VALUES (101, :c, 1, 2026, current_date - 20, current_date - 8, 'closed', now(), 1), (101, :c2, 2, 2026, current_date - 7, current_date + 6, 'open', NULL, NULL)", ['c' => $cal, 'c2' => $cal]);
$open = (string) one('SELECT current_date - 7');
post($dana, '/receipts/save.php', ['area' => $w['dry'], 'supplier' => $w['sysco'], 'received_on' => date('Y-m-d', strtotime('-10 days')), 'lines' => json_encode([['ingredient' => 'L-FLOUR', 'qty' => 1, 'unit' => 'bag50', 'unit_cost' => 30]])]);
$g8 = last_id('goods_receipts');
$r = post($dana, '/receipts/post.php', ['receipt' => $g8]);
$t = q("SELECT id, business_date::text AS d, note FROM inventory_transactions WHERE reference_kind = 'goods_receipt' AND reference_id = :g", ['g' => $g8])[0] ?? [];
ok($r['code'] === 302 && ($t['d'] ?? '') === $open, 'a receipt dated ten days ago (a closed period) posts and lands on the open period\'s first day');
